(()=>{const panel=document.getElementById('studio-analytics'),box=document.getElementById('studio-analytics-results'),button=document.getElementById('studio-analytics-refresh');const el=(tag,value)=>{const e=document.createElement(tag);e.textContent=value;return e;};async function load(){panel.hidden=false;panel.scrollIntoView({behavior:'smooth'});button.disabled=true;box.replaceChildren(el('p','Loading your saved results…'));try{const r=await fetch('/api/studio/analytics'),d=await r.json();if(!r.ok)throw Error(d.error);box.replaceChildren(el('p',d.method),el('p',d.jobsReviewed+' jobs reviewed · '+d.active+' active · '+d.archived+' archived'));const metrics=el('div','');metrics.className='studio-health';for(const [name,value] of [['Measured post sources',d.measuredSources],['Reported views',d.totals.views],['Reported enquiries',d.totals.enquiries],['Reported sales',d.totals.sales]]){const card=el('article','');card.append(el('span',name),el('strong',String(value)));metrics.append(card);}box.append(metrics);if(!d.results.length)box.append(el('p','No measured posts yet. Open an approved job’s publishing handoff and record actual results with a public post URL.'));for(const row of d.results){const card=el('article','');card.className='record';card.append(el('h3',row.title),el('p',new Date(row.recordedAt).toLocaleString()+' · '+row.views+' views · '+row.enquiries+' enquiries · '+row.sales+' sales'),el('p',row.learning));const link=el('a','Open public source');link.href=row.source;link.target='_blank';link.rel='noopener noreferrer';const open=el('button','Open creative job');open.onclick=()=>window.openStudioJob?.(row.jobId);card.append(link,open);box.append(card);}}catch(e){box.replaceChildren(el('p',e.message));}finally{button.disabled=false;}}button.onclick=load;window.addEventListener('studio-analytics-open',load);})();
